valuesYaml:
bootstrap:
  oauth:
    enabled: true
    issuerUrl: ${OIDC_ISSUER_URL}
    clientId: ${OIDC_CLIENT_ID}
    clientSecret: ${OIDC_CLIENT_SECRET}
    tokenEndpointAuthMethod: client_secret_basic
    buttonText: "Sign in with SSO"
immich:
  externalUrl: https://${APP_HOST}
ingress:
  enabled: true
  host: ${APP_HOST}
  forwardAuth: ${FORWARD_AUTH}
